parameters.jsonBody:
={{ JSON.stringify({
  parent: { database_id: $env.NOTION_DATABASE_ID },
  properties: {
    'Name': { title: [{ text: { content: $json.client + ' · ' + $json.platform + ' · ' + $json.content_type } }] },
    'Request ID': { rich_text: [{ text: { content: String($json.request_id).slice(0, 1900) } }] },
    'Client': { rich_text: [{ text: { content: String($json.client).slice(0, 1900) } }] },
    'Platform': { select: { name: $json.platform } },
    'Status': { select: { name: 'Drafting' } },
    'Priority': { select: { name: $json.priority } },
    'Publish date': { date: { start: $json.publish_at } },
    'Requested by': { rich_text: [{ text: { content: String($json.requested_by).slice(0, 1900) } }] },
    'Revision': { number: 0 }
  }
}) }}

parameters.jsonOutput:
={{ JSON.stringify((() => {
  const base = $('Save tracker page id').first().json;
  const page = $json.error ? null : ($json.results || [])[0];
  const prop = (k) => (page && page.properties && page.properties[k]) || {};
  const text = (k) => (prop(k).title || prop(k).rich_text || []).map((t) => t.plain_text ?? (t.text && t.text.content) ?? '').join('').trim();
  const list = (s) => s.split(',').map((w) => w.trim()).filter((w) => w);
  const avoid = base.avoid.concat(page ? list(text('Words to avoid')) : []).map((w) => w.toLowerCase());
  return Object.assign({}, base, {
    profile_status: page ? 'found' : ($json.error ? 'unavailable' : 'none'),
    brand_voice: page ? text('Brand voice') : '',
    required_hashtags: page ? list(text('Hashtags')) : [],
    sign_off: page ? text('Sign-off') : '',
    account_manager: (page && text('Account manager')) || base.requested_by,
    tone: base.tone || (prop('Default tone').select && prop('Default tone').select.name) || 'Warm & friendly',
    avoid: avoid.filter((w, i) => avoid.indexOf(w) === i)
  });
})()) }}

parameters.jsonBody:
={{ JSON.stringify({
  model: $env.LLM_MODEL,
  temperature: 0.7,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: "You write social media copy for restaurants and hospitality brands. Write in the requested tone, for the requested platform and content type, following the client's brand_voice when it is given. Never use any of the words_to_avoid. Always include the required_hashtags, and end the caption with the sign_off when it is given. If feedback is present, rewrite the previous draft to address it. Reply with a JSON object only, with these keys: hook, caption, hashtags (array of strings), call_to_action, alt_text, visual_direction, revision_note." },
    { role: 'user', content: JSON.stringify({
        client: $json.client, platform: $json.platform, content_type: $json.content_type, brief: $json.brief,
        tone: $json.tone, brand_voice: $json.brand_voice, words_to_avoid: $json.avoid,
        required_hashtags: $json.required_hashtags, sign_off: $json.sign_off, publish_date: $json.publish_at,
        revision: $json.revision, feedback: $json.feedback, format_note: $json.format_note || '' }) }
  ]
}) }}

assignments.value:
={{ [
  ($json.char_count <= $json.char_limit ? '✅' : '⚠️') + ' Length: ' + $json.char_count + '/' + $json.char_limit + ' characters',
  ($json.hashtag_count <= $json.hashtag_limit ? '✅' : '⚠️') + ' Hashtags: ' + $json.hashtag_count + '/' + $json.hashtag_limit,
  $json.avoided_words_found.length ? '⚠️ Words to avoid found: ' + $json.avoided_words_found.join(', ') : '✅ No words from the avoid list',
  ($json.required_hashtags || []).length ? ($json.missing_hashtags.length ? '⚠️ Missing client hashtags: ' + $json.missing_hashtags.join(', ') : '✅ Client hashtags included') : ''
].filter(l => l).join('\n') }}

